window.CODE_INDEX = {"classes":{"AppLogic":{"appearsIn":[["collection","h-sequence","Find a hidden artifact and look at it \u00b7 sequence"],["editorial","h-classes","Logic \u00b7 class diagram"],["home-menu","h-sequence","Jump to a wonder, or switch language \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens talk through"],["photo-gallery","h-classes","Logic \u00b7 class diagram"],["photo-gallery","h-sequence","Swipe across the wall and open a photo \u00b7 sequence"],["splash","h-classes","Logic \u00b7 class diagram"],["splash","h-sequence","Launch the app \u00b7 sequence"],["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class AppLogic {\n  Size _appSize = Size.zero;\n\n  /// Indicates to the rest of the app that bootstrap has not completed.\n  /// The router will use this to prevent redirects while bootstrapping.\n  bool isBootstrapComplete = false;\n\n  /// Indicates which orientations the app will allow be default. Affects Android/iOS devices only.\n  /// Defaults to both landscape (hz) and portrait (vt)\n  List<Axis> supportedOrientations = [Axis.vertical, Axis.horizontal];\n\n  /// Allow a view to override the currently supported orientations. For example, [FullscreenVideoViewer] always wants to enable both landscape and portrait.\n  /// If a view sets this override, they are responsible for setting it back to null when finished.\n  List<Axis>? _supportedOrientationsOverride;\n  set supportedOrientationsOverride(List<Axis>? value) {\n    if (_supportedOrientationsOverride != value) {\n      _supportedOrientationsOverride = value;\n      _updateSystemOrientation();\n    }\n  }\n\n  /// Initialize the app and all main actors.\n  /// Loads settings, sets up services etc.\n  Future<void> bootstrap() async {\n    debugPrint('bootstrap start...');\n    // Set min-sizes for desktop apps\n    // TODO: Test on Linux and confirm whether it's safe to call there, according to issue #183 its not.\n    if (!kIsWeb && (PlatformInfo.isWindows || PlatformInfo.isMacOS)) {\n      await DesktopWindow.setMinWindowSize($styles.sizes.minAppSize);\n    }\n\n    if (kIsWeb) {\n      // SB: This is intentionally not a debugPrint, as it's a message for users who open the console on web.\n      // Display if running in WASM mode.\n      const isCompiledWithWasm = bool.fromEnvironment('dart.tool.dart2wasm');\n      final isRunningWithWasm = isCompiledWithWasm || isWasmOptInFromBootstrap;\n      PackageInfo packageInfo = await PackageInfo.fromPlatform();\n      print(\n        '''Thanks for checking out Wonderous on the web!\n        If you encounter any issues please report them at https://github.com/gskinnerTeam/flutter-wonderous-app/issues.\n        Version: ${packageInfo.version}  -  WASM-enabled: $isRunningWithWasm''',\n      );\n      // Required on web to automatically enable accessibility features\n      WidgetsFlutterBinding.ensureInitialized().ensureSemantics();\n    }\n\n    // Load any bitmaps the views might need\n    await AppBitmaps.init();\n\n    // Set preferred refresh rate to the max possible (the OS may ignore this)\n    if (!kIsWeb && PlatformInfo.isAndroid) {\n      await FlutterDisplayMode.setHighRefreshRate();\n    }\n\n    // Settings\n    await settingsLogic.load();\n\n    // Localizations\n    await localeLogic.load();\n\n    // Wonders Data\n    wondersLogic.init();\n\n    // Events\n    timelineLogic.init();\n\n    // Collectibles\n    collectiblesLogic.init();\n    await collectiblesLogic.load();\n\n    // Wait at least 1 frame to give GoRouter time to catch the initial deeplink\n    await Future.delayed(1.milliseconds);\n\n    // Flag bootStrap as complete\n    isBootstrapComplete = true;\n\n    // Load initial view (replace empty initial view which is covered by a native splash screen)\n    bool showIntro = settingsLogic.hasCompletedOnboarding.value == false;\n\n    // Use Router.neglect so /splash is replaced in browser history, preventing /splash from appearing as a back-navigation target.\n    final navigatorContext = appRouter.routerDelegate.navigatorKey.currentContext;\n    void doNavigate() {\n      if (showIntro) {\n        debugPrint('Shifting to intro screen');\n        appRouter.go(ScreenPaths.intro);\n      } else {\n        debugPrint('Shifting to initialDeeplink: $initialDeeplink (or home)');\n        appRouter.go(initialDeeplink ?? ScreenPaths.home);\n      }\n    }\n\n    if (navigatorContext != null) {\n      Router.neglect(navigatorContext, doNavigate);\n    } else {\n      doNavigate();\n    }\n  }\n\n  Future<T?> showFullscreenDialogRoute<T>(\n    BuildContext context,\n    Widget child, {\n    bool transparent = false,\n  }) async {\n    return await Navigator.of(context).push<T>(\n      PageRoutes.dialog<T>(child, duration: $styles.times.pageTransition),\n    );\n  }\n\n  /// Called from the UI layer once a MediaQuery has been obtained\n  void handleAppSizeChanged(Size appSize) {\n    /// Disable landscape layout on smaller form factors\n    bool isSmall = display.size.shortestSide / display.devicePixelRatio < 600;\n    supportedOrientations = isSmall ? [Axis.vertical] : [Axis.vertical, Axis.horizontal];\n    _updateSystemOrientation();\n    _appSize = appSize;\n  }\n\n  Display get display => PlatformDispatcher.instance.displays.first;\n\n  bool shouldUseNavRail() => _appSize.width > _appSize.height && _appSize.height > 250;\n\n  void _updateSystemOrientation() {\n    final axisList = _supportedOrientationsOverride ?? supportedOrientations;\n    //debugPrint('updateDeviceOrientation, supportedAxis: $axisList');\n    final orientations = <DeviceOrientation>[];\n    if (axisList.contains(Axis.vertical)) {\n      orientations.addAll([\n        DeviceOrientation.portraitUp,\n        DeviceOrientation.portraitDown,\n      ]);\n    }\n    if (axisList.contains(Axis.horizontal)) {\n      orientations.addAll([\n        DeviceOrientation.landscapeLeft,\n        DeviceOrientation.landscapeRight,\n      ]);\n    }\n    SystemChrome.setPreferredOrientations(orientations);\n  }\n\n  void precacheUrl(String url, BuildContext context) async {\n    await precacheImage(\n      AssetImage(url),\n      context,\n      onError: (error, stackTrace) {\n        print('Loading $url failed - ${error.toString()}');\n      },\n    );\n  }\n\n  void precacheIcons(BuildContext context) {\n    // Precache the active and idle icons for the navigation bar.\n    List<String> urls = [];\n    for (var i = 0; i < 2; i++) {\n      urls.add('${ImagePaths.common}/tab-editorial${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-photos${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-artifacts${i == 0 ? '-active' : ''}.png');\n      urls.add('${ImagePaths.common}/tab-timeline${i == 0 ? '-active' : ''}.png');\n    }\n    for (var url in urls) {\n      precacheUrl(url, context);\n    }\n  }\n\n  void precacheWonderImages(BuildContext context) {\n    List<String> urls = [\n      '${ImagePaths.root}/chichen_itza/chichen.png',\n      '${ImagePaths.root}/chichen_itza/foreground-left.png',\n      '${ImagePaths.root}/chichen_itza/foreground-right.png',\n      '${ImagePaths.root}/chichen_itza/top-left.png',\n      '${ImagePaths.root}/chichen_itza/top-right.png',\n      '${ImagePaths.root}/chichen_itza/sun.png',\n      '${ImagePaths.root}/christ_the_redeemer/redeemer.png',\n      '${ImagePaths.root}/christ_the_redeemer/foreground-left.png',\n      '${ImagePaths.root}/christ_the_redeemer/foreground-right.png',\n      '${ImagePaths.root}/christ_the_redeemer/sun.png',\n      '${ImagePaths.root}/colosseum/colosseum.png',\n      '${ImagePaths.root}/colosseum/foreground-left.png',\n      '${ImagePaths.root}/colosseum/foreground-right.png',\n      '${ImagePaths.root}/colosseum/sun.png',\n      '${ImagePaths.root}/great_wall_of_china/great-wall.png',\n      '${ImagePaths.root}/great_wall_of_china/foreground-left.png',\n      '${ImagePaths.root}/great_wall_of_china/foreground-right.png',\n      '${ImagePaths.root}/great_wall_of_china/sun.png',\n      '${ImagePaths.root}/machu_picchu/machu-picchu.png',\n      '${ImagePaths.root}/machu_picchu/foreground-back.png',\n      '${ImagePaths.root}/machu_picchu/foreground-front.png',\n      '${ImagePaths.root}/machu_picchu/sun.png',\n      '${ImagePaths.root}/petra/petra.png',\n      '${ImagePaths.root}/petra/foreground-left.png',\n      '${ImagePaths.root}/petra/foreground-right.png',\n      '${ImagePaths.root}/petra/moon.png',\n      '${ImagePaths.root}/pyramids/pyramids.png',\n      '${ImagePaths.root}/pyramids/foreground-back.png',\n      '${ImagePaths.root}/pyramids/foreground-front.png',\n      '${ImagePaths.root}/pyramids/moon.png',\n      '${ImagePaths.root}/taj_mahal/taj-mahal.png',\n      '${ImagePaths.root}/taj_mahal/foreground-left.png',\n      '${ImagePaths.root}/taj_mahal/foreground-right.png',\n      '${ImagePaths.root}/taj_mahal/sun.png',\n      '${ImagePaths.root}/taj_mahal/pool.png',\n    ];\n    List<String> folderNames = [\n      'chichen_itza',\n      'christ_the_redeemer',\n      'colosseum',\n      'great_wall_of_china',\n      'machu_picchu',\n      'petra',\n      'pyramids',\n      'taj_mahal',\n    ];\n\n    // Universals.\n    for (var name in folderNames) {\n      urls.add('${ImagePaths.root}/$name/flattened.jpg');\n      urls.add('${ImagePaths.root}/$name/wonder-button.png');\n      urls.add('${ImagePaths.root}/$name/photo-1.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-2.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-3.jpg');\n      urls.add('${ImagePaths.root}/$name/photo-4.jpg');\n    }\n\n    for (var url in urls) {\n      precacheUrl(url, context);\n    }\n  }\n}","file":"lib/logic/app_logic.dart","kind":"class","line":14,"members":{"_appSize":[15,15],"_supportedOrientationsOverride":[25,27],"_updateSystemOrientation":[135,152],"bootstrap":[35,110],"display":[131,131],"handleAppSizeChanged":[122,129],"isBootstrapComplete":[17,19],"precacheIcons":[164,176],"precacheUrl":[154,162],"precacheWonderImages":[178,240],"shouldUseNavRail":[133,133],"showFullscreenDialogRoute":[112,120],"supportedOrientations":[21,23],"supportedOrientationsOverride":[28,33]},"supers":[]},"ArtifactCarouselScreen":{"appearsIn":[["artifacts","h-widgets","Screen \u00b7 widget composition"],["index","h-screens","Screens \u00b7 how the user moves"],["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class ArtifactCarouselScreen extends StatefulWidget {\n  const ArtifactCarouselScreen({\n    super.key,\n    required this.type,\n    this.contentPadding = EdgeInsets.zero,\n  });\n  final WonderType type;\n  final EdgeInsets contentPadding;\n\n  @override\n  State<ArtifactCarouselScreen> createState() => _ArtifactScreenState();\n}","file":"lib/ui/screens/artifact/artifact_carousel/artifact_carousel_screen.dart","kind":"class","line":16,"members":{"ArtifactCarouselScreen":[17,21],"contentPadding":[23,23],"createState":[25,26],"type":[22,22]},"shot":"shots/code/ArtifactCarouselScreen.jpg","supers":["StatefulWidget"]},"LazyIndexedStack":{"appearsIn":[["wonder-details","h-widgets","Screen \u00b7 widget composition"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"/// A lazy-loading [IndexedStack] that loads [children] accordingly.\nclass LazyIndexedStack extends StatefulWidget {\n  const LazyIndexedStack({\n    super.key,\n    this.alignment = AlignmentDirectional.topStart,\n    this.textDirection,\n    this.sizing = StackFit.loose,\n    this.index = 0,\n    this.children = const [],\n  });\n\n  final AlignmentGeometry alignment;\n  final TextDirection? textDirection;\n  final StackFit sizing;\n  final int index;\n  final List<Widget> children;\n\n  @override\n  LazyIndexedStackState createState() => LazyIndexedStackState();\n}","file":"lib/ui/common/lazy_indexed_stack.dart","kind":"class","line":3,"members":{"LazyIndexedStack":[5,12],"alignment":[14,14],"children":[18,18],"createState":[20,21],"index":[17,17],"sizing":[16,16],"textDirection":[15,15]},"shot":"shots/code/LazyIndexedStack.jpg","supers":["StatefulWidget","LazyIndexedStackState"]},"LazyIndexedStackState":{"code":"class LazyIndexedStackState extends State<LazyIndexedStack> {\n  late List<bool> _activated = _initializeActivatedList();\n\n  List<bool> _initializeActivatedList() => List<bool>.generate(widget.children.length, (i) => i == widget.index);\n\n  @override\n  void didUpdateWidget(covariant LazyIndexedStack oldWidget) {\n    if (oldWidget.children.length != widget.children.length) {\n      _activated = _initializeActivatedList();\n    }\n    super.didUpdateWidget(oldWidget);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // Mark current index as active\n    _activated[widget.index] = true;\n    final children = List.generate(_activated.length, (i) {\n      return _activated[i] ? widget.children[i] : const SizedBox.shrink();\n    });\n    return IndexedStack(\n      alignment: widget.alignment,\n      sizing: widget.sizing,\n      textDirection: widget.textDirection,\n      index: widget.index,\n      children: children,\n    );\n  }\n}","file":"lib/ui/common/lazy_indexed_stack.dart","kind":"class","line":24,"members":{"_activated":[25,25],"_initializeActivatedList":[27,27],"build":[37,51],"didUpdateWidget":[29,35]},"supers":["State"]},"MeasurableWidget":{"appearsIn":[["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class MeasurableWidget extends SingleChildRenderObjectWidget {\n  const MeasurableWidget({super.key, required this.onChange, required Widget super.child});\n  final void Function(Size size) onChange;\n  @override\n  RenderObject createRenderObject(BuildContext context) => MeasureSizeRenderObject(onChange);\n}","file":"lib/ui/common/measurable_widget.dart","kind":"class","line":6,"members":{"MeasurableWidget":[7,7],"createRenderObject":[9,10],"onChange":[8,8]},"shot":"shots/code/MeasurableWidget.jpg","supers":["SingleChildRenderObjectWidget"]},"PhotoGallery":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["photo-gallery","h-classes","Logic \u00b7 class diagram"],["photo-gallery","h-widgets","Screen \u00b7 widget composition"],["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class PhotoGallery extends StatefulWidget {\n  const PhotoGallery({\n    super.key,\n    this.imageSize,\n    required this.collectionId,\n    required this.wonderType,\n  });\n  final Size? imageSize;\n  final String collectionId;\n  final WonderType wonderType;\n\n  @override\n  State<PhotoGallery> createState() => _PhotoGalleryState();\n}","file":"lib/ui/screens/photo_gallery/photo_gallery.dart","kind":"class","line":17,"members":{"PhotoGallery":[18,23],"collectionId":[25,25],"createState":[28,29],"imageSize":[24,24],"wonderType":[26,26]},"shot":"shots/code/PhotoGallery.jpg","supers":["StatefulWidget","_PhotoGalleryState"]},"ScreenPaths":{"appearsIn":[["editorial","h-classes","Logic \u00b7 class diagram"],["events","h-classes","Logic \u00b7 class diagram"],["home-menu","h-classes","Logic \u00b7 class diagram"],["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Pick a wonder and swipe up into it \u00b7 sequence"],["intro","h-classes","Logic \u00b7 class diagram"],["splash","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-classes","Logic \u00b7 class diagram"]],"code":"/// Shared paths / urls used across the app\nclass ScreenPaths {\n  static String splash = '/';\n  static String intro = '/welcome';\n  static String home = '/home';\n  static String settings = '/settings';\n\n  static String wonderDetails(WonderType type, {required int tabIndex}) => '$home/wonder/${type.name}?t=$tabIndex';\n\n  /// Dynamically nested pages, always added on to the existing path\n  static String video(String id) => _appendToCurrentPath('/video/$id');\n  static String search(WonderType type) => _appendToCurrentPath('/search/${type.name}');\n  static String maps(WonderType type) => _appendToCurrentPath('/maps/${type.name}');\n  static String timeline(WonderType? type) => _appendToCurrentPath('/timeline?type=${type?.name ?? ''}');\n  static String artifact(String id, {bool append = true}) =>\n      append ? _appendToCurrentPath('/artifact/$id') : '/artifact/$id';\n  static String collection(String id) => _appendToCurrentPath('/collection${id.isEmpty ? '' : '?id=$id'}');\n\n  static String _appendToCurrentPath(String newPath) {\n    final newPathUri = Uri.parse(newPath);\n    final currentUri = appRouter.routeInformationProvider.value.uri;\n    Map<String, dynamic> params = Map.of(currentUri.queryParameters);\n    params.addAll(newPathUri.queryParameters);\n    Uri? loc = Uri(\n      path: '${currentUri.path}/${newPathUri.path}'.replaceAll('//', '/'),\n      queryParameters: params,\n    );\n    return loc.toString();\n  }\n}","file":"lib/router.dart","kind":"class","line":15,"members":{"_appendToCurrentPath":[33,43],"artifact":[29,30],"collection":[31,31],"home":[19,19],"intro":[18,18],"maps":[27,27],"search":[26,26],"settings":[20,20],"splash":[17,17],"timeline":[28,28],"video":[24,25],"wonderDetails":[22,22]},"supers":[]},"WonderData":{"appearsIn":[["artifacts","h-classes","Logic \u00b7 class diagram"],["editorial","h-classes","Logic \u00b7 class diagram"],["events","h-classes","Logic \u00b7 class diagram"],["home-menu","h-widgets","Screen \u00b7 widget composition"],["home","h-classes","Logic \u00b7 class diagram"],["timeline","h-widgets","Screen \u00b7 widget composition"],["wonder-details","h-classes","Logic \u00b7 class diagram"]],"code":"class WonderData extends Equatable {\n  const WonderData({\n    required this.type,\n    required this.title,\n    required this.subTitle,\n    required this.regionTitle,\n    this.startYr = 0,\n    this.endYr = 0,\n    this.artifactStartYr = 0,\n    this.artifactEndYr = 0,\n    this.artifactCulture = '',\n    this.artifactGeolocation = '',\n    this.lat = 0,\n    this.lng = 0,\n    this.imageIds = const [],\n    required this.unsplashCollectionId,\n    required this.pullQuote1Top,\n    required this.pullQuote1Bottom,\n    required this.pullQuote1Author,\n    this.pullQuote2 = '',\n    this.pullQuote2Author = '',\n    this.callout1 = '',\n    this.callout2 = '',\n    this.facts = const [],\n    required this.historyInfo1,\n    required this.historyInfo2,\n    required this.constructionInfo1,\n    required this.constructionInfo2,\n    required this.locationInfo1,\n    required this.locationInfo2,\n    required this.videoId,\n    this.videoCaption = '',\n    this.mapCaption = '',\n    required this.events,\n    this.highlightArtifacts = const [],\n    this.hiddenArtifacts = const [],\n    this.searchData = const [],\n    this.searchSuggestions = const [],\n  });\n\n  final WonderType type;\n  final String title;\n  final String subTitle;\n  final String regionTitle;\n  final String historyInfo1;\n  final String historyInfo2;\n  final String constructionInfo1;\n  final String constructionInfo2;\n  final String locationInfo1;\n  final String locationInfo2;\n  final String pullQuote1Top;\n  final String pullQuote1Bottom;\n  final String pullQuote1Author;\n  final String pullQuote2;\n  final String pullQuote2Author;\n  final String callout1;\n  final String callout2;\n  final String unsplashCollectionId;\n  final String videoId;\n  final String videoCaption;\n  final String mapCaption;\n  final List<String> imageIds;\n  final List<String> facts;\n  final int startYr;\n  final int endYr;\n  final int artifactStartYr;\n  final int artifactEndYr;\n  final String artifactCulture;\n  final String artifactGeolocation;\n  final double lat;\n  final double lng;\n  final List<String> highlightArtifacts; // IDs used to assemble HighlightsData, should not be used directly\n  final List<String> hiddenArtifacts; // IDs used to assemble CollectibleData, should not be used directly\n  final Map<int, String> events;\n  final List<SearchData> searchData;\n  final List<String> searchSuggestions;\n\n  String get titleWithBreaks => title.replaceFirst(' ', '\\n');\n\n  @override\n  List<Object?> get props => [type, title, historyInfo1, imageIds, facts];\n}","file":"lib/logic/data/wonder_data.dart","kind":"class","line":5,"members":{"WonderData":[6,43],"artifactCulture":[72,72],"artifactEndYr":[71,71],"artifactGeolocation":[73,73],"artifactStartYr":[70,70],"callout1":[60,60],"callout2":[61,61],"constructionInfo1":[51,51],"constructionInfo2":[52,52],"endYr":[69,69],"events":[78,78],"facts":[67,67],"hiddenArtifacts":[77,77],"highlightArtifacts":[76,76],"historyInfo1":[49,49],"historyInfo2":[50,50],"imageIds":[66,66],"lat":[74,74],"lng":[75,75],"locationInfo1":[53,53],"locationInfo2":[54,54],"mapCaption":[65,65],"props":[84,85],"pullQuote1Author":[57,57],"pullQuote1Bottom":[56,56],"pullQuote1Top":[55,55],"pullQuote2":[58,58],"pullQuote2Author":[59,59],"regionTitle":[48,48],"searchData":[79,79],"searchSuggestions":[80,80],"startYr":[68,68],"subTitle":[47,47],"title":[46,46],"titleWithBreaks":[82,82],"type":[45,45],"unsplashCollectionId":[62,62],"videoCaption":[64,64],"videoId":[63,63]},"supers":["Equatable"]},"WonderDetailsScreen":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class WonderDetailsScreen extends StatefulWidget with GetItStatefulWidgetMixin {\n  WonderDetailsScreen({super.key, required this.type, this.tabIndex = 0});\n  final WonderType type;\n  final int tabIndex;\n\n  @override\n  State<WonderDetailsScreen> createState() => _WonderDetailsScreenState();\n}","file":"lib/ui/screens/wonder_details/wonders_details_screen.dart","kind":"class","line":10,"members":{"WonderDetailsScreen":[11,11],"createState":[15,16],"tabIndex":[13,13],"type":[12,12]},"shot":"shots/code/WonderDetailsScreen.jpg","supers":["StatefulWidget","GetItStatefulWidgetMixin","_WonderDetailsScreenState"]},"WonderDetailsTabMenu":{"appearsIn":[["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class WonderDetailsTabMenu extends StatelessWidget {\n  static const double buttonInset = 12;\n  static const double homeBtnSize = 74;\n  static const double minTabSize = 25;\n  static const double maxTabSize = 100;\n\n  const WonderDetailsTabMenu({\n    super.key,\n    required this.tabController,\n    this.showBg = false,\n    required this.wonderType,\n    this.axis = Axis.horizontal,\n    required this.onTap,\n  });\n\n  final TabController tabController;\n  final bool showBg;\n  final WonderType wonderType;\n  final Axis axis;\n  bool get isVertical => axis == Axis.vertical;\n\n  final void Function(int index) onTap;\n\n  @override\n  Widget build(BuildContext context) {\n    Color iconColor = showBg ? $styles.colors.black : $styles.colors.white;\n    // Measure available size after subtracting the home button size and insets\n    final availableSize = ((isVertical ? context.heightPx : context.widthPx) - homeBtnSize - $styles.insets.md);\n    // Calculate tabBtnSize based on availableSize\n    final double tabBtnSize = (availableSize / 4).clamp(minTabSize, maxTabSize);\n    // Figure out some extra gap, in the case that the tabBtns are wider than the homeBtn\n    final double gapAmt = max(0, tabBtnSize - homeBtnSize);\n    // Store off safe areas which we will need to respect in the layout below\n    final double safeAreaBtm = context.mq.padding.bottom, safeAreaTop = context.mq.padding.top;\n    // Insets the bg from the rounded wonder icon making it appear offset. The tab btns will use the same padding.\n    final buttonInsetPadding = isVertical ? EdgeInsets.only(right: buttonInset) : EdgeInsets.only(top: buttonInset);\n    return Padding(\n      padding: isVertical ? EdgeInsets.only(top: safeAreaTop) : EdgeInsets.zero,\n      child: Stack(\n        children: [\n          /// Background, animates in and out based on `showBg`,\n          /// has padding along the inside edge which makes the home-btn appear to hang over the edge.\n          Positioned.fill(\n            child: Padding(\n              padding: buttonInsetPadding,\n              child: AnimatedOpacity(\n                duration: $styles.times.fast,\n                opacity: showBg ? 1 : 0,\n                child: Container(\n                  decoration: BoxDecoration(\n                    color: $styles.colors.white,\n                    borderRadius: isVertical ? BorderRadius.only(topRight: Radius.circular(32)) : null,\n                  ),\n                ),\n              ),\n            ),\n          ),\n\n          /// Buttons\n          /// A centered row / column of tabButtons w/ an wonder home button\n          Padding(\n            /// When in hz mode add safeArea bottom padding, vertical layout should not need it\n            padding: EdgeInsets.only(bottom: isVertical ? 0 : safeAreaBtm),\n            child: SizedBox(\n              width: isVertical ? null : double.infinity,\n              height: isVertical ? double.infinity : null,\n              child: FocusTraversalGroup(\n                child: Flex(\n                  direction: axis,\n                  mainAxisAlignment: MainAxisAlignment.center,\n                  crossAxisAlignment: CrossAxisAlignment.center,\n                  mainAxisSize: MainAxisSize.min,\n                  children: [\n                    /// Home btn\n                    Padding(\n                      /// Small amt of padding for home-btn\n                      padding: isVertical\n                          ? EdgeInsets.only(left: $styles.insets.xs)\n                          : EdgeInsets.only(bottom: $styles.insets.xs),\n                      child: _WonderHomeBtn(\n                        size: homeBtnSize,\n                        wonderType: wonderType,\n                        borderSize: showBg ? 6 : 2,\n                      ),\n                    ),\n                    Gap(gapAmt),\n\n                    /// A second Row / Col holding tab buttons\n                    /// Add the btn inset padding so they will be centered on the colored background\n                    Padding(\n                      padding: buttonInsetPadding,\n                      child: Flex(\n                        direction: axis,\n                        mainAxisAlignment: MainAxisAlignment.center,\n                        crossAxisAlignment: CrossAxisAlignment.center,\n                        mainAxisSize: MainAxisSize.min,\n                        children: [\n                          /// Tabs\n                          _TabBtn(\n                            0,\n                            tabController,\n                            iconImg: 'editorial',\n                            label: $strings.wonderDetailsTabLabelInformation,\n                            color: iconColor,\n                            axis: axis,\n                            mainAxisSize: tabBtnSize,\n                            onTap: onTap,\n                          ),\n                          _TabBtn(\n                            1,\n                            tabController,\n                            iconImg: 'photos',\n                            label: $strings.wonderDetailsTabLabelImages,\n                            color: iconColor,\n                            axis: axis,\n                            mainAxisSize: tabBtnSize,\n                            onTap: onTap,\n                          ),\n                          _TabBtn(\n                            2,\n                            tabController,\n                            iconImg: 'artifacts',\n                            label: $strings.wonderDetailsTabLabelArtifacts,\n                            color: iconColor,\n                            axis: axis,\n                            mainAxisSize: tabBtnSize,\n                            onTap: onTap,\n                          ),\n                          _TabBtn(\n                            3,\n                            tabController,\n                            iconImg: 'timeline',\n                            label: $strings.wonderDetailsTabLabelEvents,\n                            color: iconColor,\n                            axis: axis,\n                            mainAxisSize: tabBtnSize,\n                            onTap: onTap,\n                          ),\n                        ],\n                      ),\n                    ),\n                  ],\n                ),\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}","file":"lib/ui/screens/wonder_details/wonder_details_tab_menu.dart","kind":"class","line":3,"members":{"WonderDetailsTabMenu":[9,16],"axis":[21,21],"build":[26,152],"buttonInset":[4,4],"homeBtnSize":[5,5],"isVertical":[22,22],"maxTabSize":[7,7],"minTabSize":[6,6],"onTap":[24,24],"showBg":[19,19],"tabController":[18,18],"wonderType":[20,20]},"shot":"shots/code/WonderDetailsTabMenu.jpg","supers":["StatelessWidget"]},"WonderEditorialScreen":{"appearsIn":[["editorial","h-classes","Logic \u00b7 class diagram"],["editorial","h-widgets","Screen \u00b7 widget composition"],["index","h-screens","Screens \u00b7 how the user moves"],["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class WonderEditorialScreen extends StatefulWidget {\n  const WonderEditorialScreen(this.data, {super.key, required this.contentPadding});\n  final WonderData data;\n  //final void Function(double scrollPos) onScroll;\n  final EdgeInsets contentPadding;\n\n  @override\n  State<WonderEditorialScreen> createState() => _WonderEditorialScreenState();\n}","file":"lib/ui/screens/editorial/editorial_screen.dart","kind":"class","line":43,"members":{"WonderEditorialScreen":[44,44],"contentPadding":[47,47],"createState":[49,50],"data":[45,45]},"shot":"shots/code/WonderEditorialScreen.jpg","supers":["StatefulWidget","_WonderEditorialScreenState"]},"WonderEvents":{"appearsIn":[["events","h-classes","Logic \u00b7 class diagram"],["events","h-widgets","Screen \u00b7 widget composition"],["index","h-screens","Screens \u00b7 how the user moves"],["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class WonderEvents extends StatefulWidget {\n  const WonderEvents({super.key, required this.type, this.contentPadding = EdgeInsets.zero});\n  final WonderType type;\n  final EdgeInsets contentPadding;\n  @override\n  State<WonderEvents> createState() => _WonderEventsState();\n}","file":"lib/ui/screens/wonder_events/wonder_events.dart","kind":"class","line":23,"members":{"WonderEvents":[24,24],"contentPadding":[26,26],"createState":[27,28],"type":[25,25]},"shot":"shots/code/WonderEvents.jpg","supers":["StatefulWidget","_WonderEventsState"]},"WonderType":{"appearsIn":[["wonder-details","h-classes","Logic \u00b7 class diagram"]],"code":"enum WonderType {\n  chichenItza,\n  christRedeemer,\n  colosseum,\n  greatWall,\n  machuPicchu,\n  petra,\n  pyramidsGiza,\n  tajMahal,\n}","file":"lib/logic/data/wonder_type.dart","kind":"enum","line":1,"members":{"chichenItza":[2,2],"christRedeemer":[3,3],"colosseum":[4,4],"greatWall":[5,5],"machuPicchu":[6,6],"petra":[7,7],"pyramidsGiza":[8,8],"tajMahal":[9,9]},"supers":[]},"WondersLogic":{"appearsIn":[["events","h-classes","Logic \u00b7 class diagram"],["events","h-sequence","Read the events and open the global timeline \u00b7 sequence"],["home-menu","h-classes","Logic \u00b7 class diagram"],["home-menu","h-sequence","Jump to a wonder, or switch language \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens talk through"],["splash","h-classes","Logic \u00b7 class diagram"],["splash","h-sequence","Launch the app \u00b7 sequence"],["timeline","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class WondersLogic {\n  List<WonderData> all = [];\n\n  final int timelineStartYear = -3000;\n  final int timelineEndYear = 2200;\n\n  WonderData getData(WonderType value) {\n    WonderData? result = all.firstWhereOrNull((w) => w.type == value);\n    if (result == null) throw ('Could not find data for wonder type $value');\n    return result;\n  }\n\n  void init() {\n    all = [\n      GreatWallData(),\n      PetraData(),\n      ColosseumData(),\n      ChichenItzaData(),\n      MachuPicchuData(),\n      TajMahalData(),\n      ChristRedeemerData(),\n      PyramidsGizaData(),\n    ];\n  }\n}","file":"lib/logic/wonders_logic.dart","kind":"class","line":12,"members":{"all":[13,13],"getData":[18,22],"init":[24,35],"timelineEndYear":[16,16],"timelineStartYear":[15,15]},"supers":[]},"_PhotoGalleryState":{"appearsIn":[["photo-gallery","h-classes","Logic \u00b7 class diagram"],["photo-gallery","h-sequence","Swipe across the wall and open a photo \u00b7 sequence"]],"code":"class _PhotoGalleryState extends State<PhotoGallery> {\n  static const int _gridSize = 5;\n  // Index starts in the middle of the grid (eg, 25 items, index will start at 13)\n  int _index = ((_gridSize * _gridSize) / 2).round();\n  Offset _lastSwipeDir = Offset.zero;\n  final double _scale = 1;\n  bool _skipNextOffsetTween = false;\n  late Duration swipeDuration = $styles.times.med * .4;\n  final _photoIds = ValueNotifier<List<String>>([]);\n  int get _imgCount => pow(_gridSize, 2).round();\n\n  late final List<FocusNode> _focusNodes = List.generate(_imgCount, (index) => FocusNode());\n\n  //TODO: Remove this field (and associated workarounds) once web properly supports ClipPath (https://github.com/flutter/flutter/issues/124675)\n  final bool useClipPathWorkAroundForWeb = kIsWeb;\n\n  @override\n  void initState() {\n    super.initState();\n    _initPhotoIds();\n    _focusNodes[_index].requestFocus();\n  }\n\n  Future<void> _initPhotoIds() async {\n    var ids = unsplashLogic.getCollectionPhotos(widget.collectionId);\n    if (ids != null && ids.isNotEmpty) {\n      // Ensure we have enough images to fill the grid, repeat if necessary\n      while (ids.length < _imgCount) {\n        ids.addAll(List.from(ids));\n        if (ids.length > _imgCount) ids.length = _imgCount;\n      }\n    }\n    setState(() => _photoIds.value = ids ?? []);\n  }\n\n  void _setIndex(int value, {bool skipAnimation = false}) {\n    if (value < 0 || value >= _imgCount) return;\n    _skipNextOffsetTween = skipAnimation;\n    setState(() => _index = value);\n    _focusNodes[value].requestFocus();\n  }\n\n  /// Determine the required offset to show the current selected index.\n  /// index=0 is top-left, and the index=max is bottom-right.\n  Offset _calculateCurrentOffset(double padding, Size size) {\n    double halfCount = (_gridSize / 2).floorToDouble();\n    Size paddedImageSize = Size(size.width + padding, size.height + padding);\n    // Get the starting offset that would show the top-left image (index 0)\n    final originOffset = Offset(\n      halfCount * paddedImageSize.width,\n      halfCount * paddedImageSize.height,\n    );\n    // Add the offset for the row/col\n    int col = _index % _gridSize;\n    int row = (_index / _gridSize).floor();\n    final indexedOffset = Offset(-paddedImageSize.width * col, -paddedImageSize.height * row);\n    return originOffset + indexedOffset;\n  }\n\n  /// Used for hiding collectibles around the photo grid.\n  int _getCollectibleIndex() {\n    return switch (widget.wonderType) {\n      WonderType.chichenItza || WonderType.petra => 0,\n      WonderType.colosseum || WonderType.pyramidsGiza => _gridSize - 1,\n      WonderType.christRedeemer || WonderType.machuPicchu => _imgCount - 1,\n      WonderType.greatWall || WonderType.tajMahal => _imgCount - _gridSize,\n    };\n  }\n\n  bool _handleKeyDown(KeyDownEvent event) {\n    final key = event.logicalKey;\n    Map<LogicalKeyboardKey, int> keyActions = {\n      LogicalKeyboardKey.arrowUp: -_gridSize,\n      LogicalKeyboardKey.arrowDown: _gridSize,\n      LogicalKeyboardKey.arrowRight: 1,\n      LogicalKeyboardKey.arrowLeft: -1,\n    };\n\n    // Apply key action, exit early if no action is defined\n    int? actionValue = keyActions[key];\n    if (actionValue == null) return false;\n    int newIndex = _index + actionValue;\n\n    // Block actions along edges of the grid\n    bool isRightSide = _index % _gridSize == _gridSize - 1;\n    bool isLeftSide = _index % _gridSize == 0;\n    bool outOfBounds = newIndex < 0 || newIndex >= _imgCount;\n    if ((isRightSide && key == LogicalKeyboardKey.arrowRight) ||\n        (isLeftSide && key == LogicalKeyboardKey.arrowLeft) ||\n        outOfBounds) {\n      return false;\n    }\n    _setIndex(newIndex);\n    return true;\n  }\n\n  /// Converts a swipe direction into a new index\n  void _handleSwipe(Offset dir) {\n    // Calculate new index, y swipes move by an entire row, x swipes move one index at a time\n    int newIndex = _index;\n    if (dir.dy != 0) newIndex += _gridSize * (dir.dy > 0 ? -1 : 1);\n    if (dir.dx != 0) newIndex += (dir.dx > 0 ? -1 : 1);\n    // After calculating new index, exit early if we don't like it...\n    if (newIndex < 0 || newIndex > _imgCount - 1) {\n      return; // keep the index in range\n    }\n    if (dir.dx < 0 && newIndex % _gridSize == 0) {\n      return; // prevent right-swipe when at right side\n    }\n    if (dir.dx > 0 && newIndex % _gridSize == _gridSize - 1) {\n      return; // prevent left-swipe when at left side\n    }\n    _lastSwipeDir = dir;\n    AppHaptics.lightImpact();\n    _setIndex(newIndex);\n  }\n\n  Future<void> _handleImageTapped(int index, bool isSelected) async {\n    if (_checkCollectibleIndex(index) && isSelected) return;\n    if (_index == index) {\n      final urls = _photoIds.value.map((e) {\n        return UnsplashPhotoData.getSelfHostedUrl(e, UnsplashPhotoSize.xl);\n      }).toList();\n      int? newIndex = await appLogic.showFullscreenDialogRoute(\n        context,\n        FullscreenUrlImgViewer(urls: urls, index: _index),\n      );\n\n      if (newIndex != null) {\n        _setIndex(newIndex, skipAnimation: true);\n      }\n    } else {\n      _setIndex(index);\n    }\n  }\n\n  void _handleImageFocusChanged(int index, bool isFocused) {\n    if (isFocused) {\n      _setIndex(index);\n    }\n  }\n\n  bool _checkCollectibleIndex(int index) {\n    return index == _getCollectibleIndex() && collectiblesLogic.isLost(widget.wonderType, 1);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return FullscreenKeyboardListener(\n      onKeyDown: _handleKeyDown,\n      child: ValueListenableBuilder<List<String>>(\n        valueListenable: _photoIds,\n        builder: (_, value, _) {\n          if (value.isEmpty) {\n            return Center(child: AppLoadingIndicator());\n          }\n          Size imgSize = context.isLandscape\n              ? Size(context.widthPx * .5, context.heightPx * .66)\n              : Size(context.widthPx * .66, context.heightPx * .5);\n          imgSize = (widget.imageSize ?? imgSize) * _scale;\n          // Get transform offset for the current _index\n          final padding = $styles.insets.md;\n          var gridOffset = _calculateCurrentOffset(padding, imgSize);\n          gridOffset += Offset(0, -context.mq.padding.top / 2);\n          final offsetTweenDuration = _skipNextOffsetTween ? Duration.zero : swipeDuration;\n          final cutoutTweenDuration = _skipNextOffsetTween ? Duration.zero : swipeDuration * .5;\n          return _AnimatedCutoutOverlay(\n            animationKey: ValueKey(_index),\n            cutoutSize: imgSize,\n            swipeDir: _lastSwipeDir,\n            duration: cutoutTweenDuration,\n            opacity: _scale == 1 ? .7 : .5,\n            enabled: useClipPathWorkAroundForWeb == false,\n            child: SafeArea(\n              bottom: false,\n              // Place content in overflow box, to allow it to flow outside the parent\n              child: OverflowBox(\n                maxWidth: _gridSize * imgSize.width + padding * (_gridSize - 1),\n                maxHeight: _gridSize * imgSize.height + padding * (_gridSize - 1),\n                alignment: Alignment.center,\n                // Detect swipes in order to change index\n                child: EightWaySwipeDetector(\n                  onSwipe: _handleSwipe,\n                  threshold: 30,\n                  // A tween animation builder moves from image to image based on current offset\n                  child: TweenAnimationBuilder<Offset>(\n                    tween: Tween(begin: gridOffset, end: gridOffset),\n                    duration: offsetTweenDuration,\n                    curve: Curves.easeOut,\n                    builder: (_, value, child) => Transform.translate(offset: value, child: child),\n                    child: FocusTraversalGroup(\n                      //policy: OrderedTraversalPolicy(),\n                      child: GridView.count(\n                        physics: NeverScrollableScrollPhysics(),\n                        crossAxisCount: _gridSize,\n                        childAspectRatio: imgSize.aspectRatio,\n                        mainAxisSpacing: padding,\n                        crossAxisSpacing: padding,\n                        children: List.generate(\n                          _imgCount,\n                          (i) => _buildImage(i, swipeDuration, imgSize),\n                        ),\n                      ),\n                    ),\n                  ),\n                ),\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _buildImage(int index, Duration swipeDuration, Size imgSize) {\n    /// Bind to collectibles.statesById because we might need to rebuild if a collectible is found.\n    return FocusTraversalOrder(\n      order: NumericFocusOrder(index.toDouble()),\n      child: ValueListenableBuilder(\n        valueListenable: collectiblesLogic.statesById,\n        builder: (_, _, _) {\n          bool isSelected = index == _index;\n          final imgUrl = _photoIds.value[index];\n          late String semanticLbl;\n          if (_checkCollectibleIndex(index)) {\n            semanticLbl = $strings.collectibleItemSemanticCollectible;\n          } else {\n            semanticLbl = !isSelected\n                ? $strings.photoGallerySemanticFocus(index + 1, _imgCount)\n                : $strings.photoGallerySemanticFullscreen(index + 1, _imgCount);\n          }\n\n          final photoWidget = TweenAnimationBuilder<double>(\n            duration: $styles.times.med,\n            curve: Curves.easeOut,\n            tween: Tween(begin: 1, end: isSelected ? 1.15 : 1),\n            builder: (_, value, child) => Transform.scale(scale: value, child: child),\n            child: UnsplashPhoto(\n              imgUrl,\n              fit: BoxFit.cover,\n              size: UnsplashPhotoSize.large,\n            ).maybeAnimate().fade(),\n          );\n\n          return MergeSemantics(\n            child: Semantics(\n              focused: isSelected,\n              image: !_checkCollectibleIndex(index),\n              liveRegion: isSelected,\n              onIncrease: () => _handleImageTapped(_index + 1, false),\n              onDecrease: () => _handleImageTapped(_index - 1, false),\n              child: _checkCollectibleIndex(index)\n                  ? Center(\n                      child: HiddenCollectible(\n                        widget.wonderType,\n                        index: 1,\n                        size: 100,\n                        focus: _focusNodes[index],\n                      ),\n                    )\n                  : AppBtn.basic(\n                      semanticLabel: semanticLbl,\n                      focusNode: _focusNodes[index],\n                      onFocusChanged: (isFocused) => _handleImageFocusChanged(index, isFocused),\n                      onPressed: () => _handleImageTapped(index, isSelected),\n                      child: ClipRRect(\n                        borderRadius: BorderRadius.circular(8),\n                        child: SizedBox(\n                          width: imgSize.width,\n                          height: imgSize.height,\n                          child: (useClipPathWorkAroundForWeb == false)\n                              ? photoWidget\n                              : Stack(\n                                  children: [\n                                    photoWidget,\n                                    // Because the web platform doesn't support clipPath, we use a workaround to highlight the selected image\n                                    Positioned.fill(\n                                      child: AnimatedOpacity(\n                                        duration: $styles.times.med,\n                                        opacity: isSelected ? 0 : ($styles.highContrast ? 0.4 : 0.7),\n                                        child: ColoredBox(color: $styles.colors.black),\n                                      ),\n                                    ),\n                                  ],\n                                ),\n                        ),\n                      ),\n                    ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n}","file":"lib/ui/screens/photo_gallery/photo_gallery.dart","kind":"class","line":32,"members":{"_buildImage":[246,325],"_calculateCurrentOffset":[74,89],"_checkCollectibleIndex":[174,176],"_focusNodes":[43,43],"_getCollectibleIndex":[91,99],"_gridSize":[33,33],"_handleImageFocusChanged":[168,172],"_handleImageTapped":[149,166],"_handleKeyDown":[101,126],"_handleSwipe":[128,147],"_imgCount":[41,41],"_index":[35,35],"_initPhotoIds":[55,65],"_lastSwipeDir":[36,36],"_photoIds":[40,40],"_scale":[37,37],"_setIndex":[67,72],"_skipNextOffsetTween":[38,38],"build":[178,244],"initState":[48,53],"swipeDuration":[39,39],"useClipPathWorkAroundForWeb":[46,46]},"supers":["State"]},"_TabBtn":{"appearsIn":[["wonder-details","h-widgets","Screen \u00b7 widget composition"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class _TabBtn extends StatelessWidget {\n  const _TabBtn(\n    this.index,\n    this.tabController, {\n    required this.iconImg,\n    required this.color,\n    required this.label,\n    required this.axis,\n    required this.mainAxisSize,\n    required this.onTap,\n  });\n\n  static const double crossBtnSize = 60;\n\n  final int index;\n  final TabController tabController;\n  final String iconImg;\n  final Color color;\n  final String label;\n  final Axis axis;\n  final double mainAxisSize;\n  final void Function(int index) onTap;\n\n  bool get _isVertical => axis == Axis.vertical;\n\n  @override\n  Widget build(BuildContext context) {\n    bool selected = tabController.index == index;\n    final MaterialLocalizations localizations = MaterialLocalizations.of(context);\n    final iconImgPath = '${ImagePaths.common}/tab-$iconImg${selected ? '-active' : ''}.png';\n    String tabLabel = localizations.tabLabel(tabIndex: index + 1, tabCount: tabController.length);\n    tabLabel = '$label: $tabLabel';\n\n    final double iconSize = min(mainAxisSize, 32);\n\n    return MergeSemantics(\n      child: Semantics(\n        selected: selected,\n        label: tabLabel,\n        child: ExcludeSemantics(\n          child: AppBtn.basic(\n            onPressed: () => onTap(index),\n            semanticLabel: label,\n            minimumSize: _isVertical ? Size(crossBtnSize, mainAxisSize) : Size(mainAxisSize, crossBtnSize),\n            // Image icon\n            child: Image.asset(\n              iconImgPath,\n              height: iconSize,\n              width: iconSize,\n              color: selected ? null : color,\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/wonder_details/wonder_details_tab_menu.dart","kind":"class","line":184,"members":{"_TabBtn":[185,194],"_isVertical":[207,207],"axis":[203,203],"build":[209,239],"color":[201,201],"crossBtnSize":[196,196],"iconImg":[200,200],"index":[198,198],"label":[202,202],"mainAxisSize":[204,204],"onTap":[205,205],"tabController":[199,199]},"shot":"shots/code/_TabBtn.jpg","supers":["StatelessWidget"]},"_WonderDetailsScreenState":{"appearsIn":[["wonder-details","h-classes","Logic \u00b7 class diagram"],["wonder-details","h-sequence","Open a wonder and switch tabs \u00b7 sequence"]],"code":"class _WonderDetailsScreenState extends State<WonderDetailsScreen>\n    with GetItStateMixin, SingleTickerProviderStateMixin {\n  late final _tabController = TabController(\n    length: 4,\n    vsync: this,\n    initialIndex: _clampIndex(widget.tabIndex),\n  )..addListener(_handleTabChanged);\n  AnimationController? _fade;\n\n  double? _tabBarSize;\n  bool _useNavRail = false;\n\n  @override\n  void didUpdateWidget(covariant WonderDetailsScreen oldWidget) {\n    if (oldWidget.tabIndex != widget.tabIndex) {\n      _tabController.index = _clampIndex(widget.tabIndex);\n    }\n    super.didUpdateWidget(oldWidget);\n  }\n\n  @override\n  void dispose() {\n    _tabController.dispose();\n    super.dispose();\n  }\n\n  int _clampIndex(int index) => index.clamp(0, 3);\n\n  void _handleTabChanged() {\n    _fade?.forward(from: 0);\n    setState(() {});\n  }\n\n  void _handleTabTapped(int index) {\n    _tabController.index = index;\n    context.go(ScreenPaths.wonderDetails(widget.type, tabIndex: _tabController.index));\n  }\n\n  void _handleTabMenuSized(Size size) {\n    setState(() {\n      _tabBarSize = (_useNavRail ? size.width : size.height) - WonderDetailsTabMenu.buttonInset;\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    _useNavRail = appLogic.shouldUseNavRail();\n\n    final wonder = wondersLogic.getData(widget.type);\n    int tabIndex = _tabController.index;\n    bool showTabBarBg = tabIndex != 1;\n    final tabBarSize = _tabBarSize ?? 0;\n    final menuPadding = _useNavRail ? EdgeInsets.only(left: tabBarSize) : EdgeInsets.only(bottom: tabBarSize);\n    return ColoredBox(\n      color: Colors.black,\n      child: Stack(\n        children: [\n          /// Fullscreen tab views\n          LazyIndexedStack(\n            index: _tabController.index,\n            children: [\n              WonderEditorialScreen(wonder, contentPadding: menuPadding),\n              PhotoGallery(collectionId: wonder.unsplashCollectionId, wonderType: wonder.type),\n              ArtifactCarouselScreen(type: wonder.type, contentPadding: menuPadding),\n              WonderEvents(type: widget.type, contentPadding: menuPadding),\n            ],\n          ),\n\n          /// Tab menu\n          Align(\n            alignment: _useNavRail ? Alignment.centerLeft : Alignment.bottomCenter,\n            child: MeasurableWidget(\n              onChange: _handleTabMenuSized,\n              child: WonderDetailsTabMenu(\n                tabController: _tabController,\n                onTap: _handleTabTapped,\n                wonderType: wonder.type,\n                showBg: showTabBarBg,\n                axis: _useNavRail ? Axis.vertical : Axis.horizontal,\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n}","file":"lib/ui/screens/wonder_details/wonders_details_screen.dart","kind":"class","line":19,"members":{"_clampIndex":[45,45],"_fade":[26,26],"_handleTabChanged":[47,50],"_handleTabMenuSized":[57,61],"_handleTabTapped":[52,55],"_tabBarSize":[28,28],"_tabController":[21,25],"_useNavRail":[29,29],"build":[63,104],"didUpdateWidget":[31,37],"dispose":[39,43]},"supers":["State","GetItStateMixin","SingleTickerProviderStateMixin"]},"_WonderEditorialScreenState":{"appearsIn":[["editorial","h-classes","Logic \u00b7 class diagram"],["editorial","h-sequence","Scroll down the story \u00b7 sequence"]],"code":"class _WonderEditorialScreenState extends State<WonderEditorialScreen> {\n  late final ScrollController _scroller = ScrollController()..addListener(_handleScrollChanged);\n  final _scrollPos = ValueNotifier(0.0);\n  final _sectionIndex = ValueNotifier(0);\n\n  @override\n  void dispose() {\n    _scroller.dispose();\n    super.dispose();\n  }\n\n  /// Various [ValueListenableBuilders] are mapped to the _scrollPos and will rebuild when it changes\n  void _handleScrollChanged() {\n    _scrollPos.value = _scroller.position.pixels;\n  }\n\n  void _handleTrackpadScroll(Offset direction) {\n    // Trackpad swipe up. Return to home if at the top.\n    if (_scroller.position.pixels == 0 && direction.dy > 0) {\n      _handleBackPressed();\n    }\n  }\n\n  void _handleBackPressed() => context.go(ScreenPaths.home);\n\n  @override\n  Widget build(BuildContext context) {\n    return LayoutBuilder(\n      builder: (_, constraints) {\n        double illustrationHeight = switch (constraints.biggest.height) {\n          < 525 => 150,\n          < 700 => 250,\n          _ => 280,\n        };\n        double minAppBarHeight = constraints.biggest.height < 700 ? 80 : 150;\n\n        /// Attempt to maintain a similar aspect ratio for the image within the app-bar\n        double maxAppBarHeight = min(context.widthPx, $styles.sizes.maxContentWidth1) * 1.2;\n        final backBtnAlign = appLogic.shouldUseNavRail() ? Alignment.topRight : Alignment.topLeft;\n        return PopRouterOnOverScroll(\n          controller: _scroller,\n          child: ColoredBox(\n            color: $styles.colors.offWhite,\n            child: TrackpadListener(\n              onScroll: _handleTrackpadScroll,\n              scrollSensitivity: 120,\n              child: Stack(\n                children: [\n                  /// Background\n                  Positioned.fill(\n                    child: ColoredBox(color: widget.data.type.bgColor),\n                  ),\n\n                  /// Top Illustration - Sits underneath the scrolling content, fades out as it scrolls\n                  SizedBox(\n                    height: illustrationHeight,\n                    child: ValueListenableBuilder<double>(\n                      valueListenable: _scrollPos,\n                      builder: (_, value, child) {\n                        // get some value between 0 and 1, based on the amt scrolled\n                        double opacity = (1 - value / 700).clamp(0, 1);\n                        return Opacity(opacity: opacity, child: child);\n                      },\n                      // This is due to a bug: https://github.com/flutter/flutter/issues/101872\n                      child: RepaintBoundary(\n                        child: _TopIllustration(\n                          widget.data.type,\n                          // Polish: Inject the content padding into the illustration as an offset, so it can center itself relative to the content\n                          // this allows the background to extend underneath the vertical side nav when it has rounded corners.\n                          fgOffset: Offset(widget.contentPadding.left / 2, 0),\n                        ),\n                      ),\n                    ),\n                  ),\n\n                  /// Scrolling content - Includes an invisible gap at the top, and then scrolls over the illustration\n                  TopCenter(\n                    child: Padding(\n                      padding: widget.contentPadding,\n                      child: SizedBox(\n                        child: FocusTraversalGroup(\n                          child: FullscreenKeyboardListScroller(\n                            scrollController: _scroller,\n                            child: CustomScrollView(\n                              controller: _scroller,\n                              scrollBehavior: ScrollConfiguration.of(context).copyWith(),\n                              key: PageStorageKey('editorial'),\n                              slivers: [\n                                /// Invisible padding at the top of the list, so the illustration shows through the btm\n                                SliverToBoxAdapter(\n                                  child: SizedBox(height: illustrationHeight),\n                                ),\n\n                                /// Text content, animates itself to hide behind the app bar as it scrolls up\n                                SliverToBoxAdapter(\n                                  child: ValueListenableBuilder<double>(\n                                    valueListenable: _scrollPos,\n                                    builder: (_, value, child) {\n                                      double offsetAmt = max(0, value * .3);\n                                      double opacity = (1 - offsetAmt / 150).clamp(0, 1);\n                                      return Transform.translate(\n                                        offset: Offset(0, offsetAmt),\n                                        child: Opacity(opacity: opacity, child: child),\n                                      );\n                                    },\n                                    child: _TitleText(widget.data, scroller: _scroller),\n                                  ),\n                                ),\n\n                                /// Collapsing App bar, pins to the top of the list\n                                SliverAppBar(\n                                  pinned: true,\n                                  collapsedHeight: minAppBarHeight,\n                                  toolbarHeight: minAppBarHeight,\n                                  expandedHeight: maxAppBarHeight,\n                                  backgroundColor: Colors.transparent,\n                                  elevation: 0,\n                                  leading: SizedBox.shrink(),\n                                  flexibleSpace: SizedBox.expand(\n                                    child: _AppBar(\n                                      widget.data.type,\n                                      scrollPos: _scrollPos,\n                                      sectionIndex: _sectionIndex,\n                                    ),\n                                  ),\n                                ),\n\n                                /// Editorial content (text and images)\n                                _ScrollingContent(\n                                  widget.data,\n                                  scrollPos: _scrollPos,\n                                  sectionNotifier: _sectionIndex,\n                                ),\n                              ],\n                            ),\n                          ),\n                        ),\n                      ),\n                    ),\n                  ),\n\n                  /// Home Btn\n                  AnimatedBuilder(\n                    animation: _scroller,\n                    builder: (_, child) {\n                      return AnimatedOpacity(\n                        opacity: _scrollPos.value > 0 ? 0 : 1,\n                        duration: $styles.times.med,\n                        child: child,\n                      );\n                    },\n                    child: Align(\n                      alignment: backBtnAlign,\n                      child: Padding(\n                        padding: EdgeInsets.all($styles.insets.sm),\n                        child: BackBtn(icon: AppIcons.north, onPressed: _handleBackPressed),\n                      ),\n                    ),\n                  ),\n                ],\n              ),\n            ),\n          ),\n        );\n      },\n    );\n  }\n}","file":"lib/ui/screens/editorial/editorial_screen.dart","kind":"class","line":53,"members":{"_handleBackPressed":[76,76],"_handleScrollChanged":[64,67],"_handleTrackpadScroll":[69,74],"_scrollPos":[55,55],"_scroller":[54,54],"_sectionIndex":[56,56],"build":[78,219],"dispose":[58,62]},"supers":["State"]},"_WonderEventsState":{"appearsIn":[["events","h-classes","Logic \u00b7 class diagram"],["events","h-sequence","Read the events and open the global timeline \u00b7 sequence"]],"code":"class _WonderEventsState extends State<WonderEvents> {\n  late final _data = wondersLogic.getData(widget.type);\n  final _eventsListKey = GlobalKey<_EventsListState>();\n  double _scrollPos = 0;\n\n  void _handleScroll(double pos) => _scrollPos = pos;\n\n  @override\n  Widget build(BuildContext context) {\n    void handleTimelineBtnPressed() => context.go(ScreenPaths.timeline(widget.type));\n    // Main view content switches between 1 and 2 column layouts\n    // On mobile, use the 2 column layout on screens close to landscape (>.85). This is primarily an optimization for foldable devices which have square-ish dimensions when opened.\n    final twoColumnAspect = PlatformInfo.isMobile ? .85 : 1;\n    bool useTwoColumnLayout = context.mq.size.aspectRatio > twoColumnAspect;\n    bool smallMode = context.heightPx < 550;\n\n    return LayoutBuilder(\n      builder: (context, constraints) {\n        return Container(\n          color: $styles.colors.black,\n          child: SafeArea(\n            bottom: false,\n            child: Stack(\n              children: [\n                /// Main view\n                Positioned.fill(\n                  top: smallMode ? 0 : $styles.insets.sm,\n                  child: Padding(\n                    padding: widget.contentPadding,\n                    child: useTwoColumnLayout ? _buildTwoColumn(context) : _buildSingleColumn(),\n                  ),\n                ),\n\n                /// Header w/ TimelineBtn\n                TopCenter(\n                  child: AppHeader(\n                    showBackBtn: false,\n                    isTransparent: true,\n                    trailing: (_) => CircleIconBtn(\n                      icon: AppIcons.timeline,\n                      onPressed: handleTimelineBtnPressed,\n                      semanticLabel: $strings.eventsListButtonOpenGlobal,\n                    ),\n                  ),\n                ),\n              ],\n            ),\n          ),\n        );\n      },\n    );\n  }\n\n  /// Landscape layout is a row, with the WonderImage on left and EventsList on the right\n  Widget _buildTwoColumn(BuildContext context) {\n    bool smallMode = context.heightPx < 550;\n    final double timelineImageSize = (context.heightPx - 200).clamp(200, 500);\n    return Padding(\n      padding: EdgeInsets.symmetric(\n        vertical: smallMode ? $styles.insets.sm : $styles.insets.lg,\n        horizontal: $styles.insets.sm,\n      ),\n      child: Row(\n        children: [\n          /// WonderImage w/ Timeline btn\n          Expanded(\n            child: CenteredBox(\n              width: $styles.sizes.maxContentWidth3,\n              child: Padding(\n                padding: EdgeInsets.symmetric(vertical: smallMode ? $styles.insets.sm : $styles.insets.lg),\n                child: Column(\n                  mainAxisSize: MainAxisSize.min,\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: [\n                    _WonderImageWithTimeline(data: _data, height: timelineImageSize),\n                    Gap(smallMode ? $styles.insets.md : $styles.insets.lg),\n                    SizedBox(width: 400, child: _TimelineBtn(type: widget.type)),\n                  ],\n                ),\n              ),\n            ),\n          ),\n\n          /// EventsList\n          Expanded(\n            child: CenteredBox(\n              width: $styles.sizes.maxContentWidth2,\n              child: _EventsList(\n                key: _eventsListKey,\n                data: _data,\n                topHeight: 100,\n                blurOnScroll: false,\n                onScroll: _handleScroll,\n                initialScrollOffset: _scrollPos,\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  /// Portrait layout is a stack with the EventsList scrolling overtop of the WonderImage\n  Widget _buildSingleColumn() {\n    return LayoutBuilder(\n      builder: (_, constraints) {\n        double topHeight = max(constraints.maxHeight * .55, 200);\n        return CenteredBox(\n          width: $styles.sizes.maxContentWidth2,\n          child: Stack(\n            children: [\n              /// Top content, sits underneath scrolling list\n              _WonderImageWithTimeline(height: topHeight, data: _data),\n\n              /// EventsList + TimelineBtn\n              Column(\n                children: [\n                  Expanded(\n                    /// EventsList\n                    child: _EventsList(\n                      key: _eventsListKey,\n                      data: _data,\n                      topHeight: topHeight,\n                      blurOnScroll: true,\n                      showTopGradient: false,\n                      onScroll: _handleScroll,\n                      initialScrollOffset: _scrollPos,\n                    ),\n                  ),\n                  Gap($styles.insets.lg),\n\n                  /// TimelineBtn\n                  _TimelineBtn(type: _data.type, width: $styles.sizes.maxContentWidth2),\n                  Gap($styles.insets.lg),\n                ],\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n}","file":"lib/ui/screens/wonder_events/wonder_events.dart","kind":"class","line":31,"members":{"_buildSingleColumn":[133,172],"_buildTwoColumn":[84,131],"_data":[32,32],"_eventsListKey":[33,33],"_handleScroll":[36,36],"_scrollPos":[34,34],"build":[38,82]},"supers":["State"]},"_WonderHomeBtn":{"appearsIn":[["wonder-details","h-widgets","Screen \u00b7 widget composition"]],"code":"class _WonderHomeBtn extends StatelessWidget {\n  const _WonderHomeBtn({required this.size, required this.wonderType, required this.borderSize});\n\n  final double size;\n  final WonderType wonderType;\n  final double borderSize;\n\n  @override\n  Widget build(BuildContext context) {\n    return CircleBtn(\n      onPressed: () => context.go(ScreenPaths.home),\n      bgColor: $styles.colors.white,\n      semanticLabel: $strings.wonderDetailsTabSemanticBack,\n      child: AnimatedContainer(\n        curve: Curves.easeOut,\n        duration: $styles.times.fast,\n        width: size - borderSize * 2,\n        height: size - borderSize * 2,\n        margin: EdgeInsets.all(borderSize),\n        decoration: BoxDecoration(\n          borderRadius: BorderRadius.circular(99),\n          color: wonderType.fgColor,\n          image: DecorationImage(image: AssetImage(wonderType.homeBtn), fit: BoxFit.fill),\n        ),\n      ),\n    );\n  }\n}","file":"lib/ui/screens/wonder_details/wonder_details_tab_menu.dart","kind":"class","line":155,"members":{"_WonderHomeBtn":[156,156],"borderSize":[160,160],"build":[162,181],"size":[158,158],"wonderType":[159,159]},"shot":"shots/code/_WonderHomeBtn.jpg","supers":["StatelessWidget"]}},"sourceUrl":"https://github.com/gskinnerTeam/flutter-wonderous-app/blob/30ccc36a276223ebbb85dbb290d6ff2facf001ed/"};
